// Approfondissements rédigés à partir des 50 thèmes de remise à niveau.
// Les formulations, exemples et questions sont originaux.
const questions = items => items.map(([q, a, correct, e], index) => {
  const shift = index % a.length;
  return { q, a: [...a.slice(shift), ...a.slice(0, shift)], c: (correct - shift + a.length) % a.length, e };
});
const chapter = (title, lesson, oral, items) => ({ title, lesson, oral, questions: questions(items) });

